132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
135	        // Idempotent create: if this request carries an Idempotency-Key we have already created an
136	        // owner for, return that original owner with 200 OK instead of creating a duplicate.
137	        String idempotencyKey = request.getHeader(IDEMPOTENCY_KEY_HEADER);
138	        boolean hasIdempotencyKey = idempotencyKey != null && !idempotencyKey.isBlank();
139	        if (hasIdempotencyKey) {
140	            Integer existingId = idempotencyKeys.get(idempotencyKey);
141	            if (existingId != null) {
142	                Owner existing = this.clinicService.findOwnerById(existingId);
143	                if (existing != null) {
144	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
145	                }
146	            }
147	        }
148	        HttpHeaders headers = new HttpHeaders();
149	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
150	        // The effective registration date (supplied, or the server date when omitted) must fall on
151	        // a business day: a weekend rolls forward to the next Monday. Everything derived from the
152	        // registration date — the stored value, the per-day limit below and the membership number —
153	        // uses this adjusted date.
154	        LocalDate effectiveDate = BusinessDays.effectiveRegistrationDate(owner.getRegistrationDate());
155	        owner.setRegistrationDate(effectiveDate);
156	        // Per-day capacity: once the day has reached its limit of newly created owners, reject
157	        // further creates for that day with 429 Too Many Requests.
158	        int ownersRegisteredToday = this.clinicService.countOwnersRegisteredOn(effectiveDate);
159	        if (ownersRegisteredToday >= DAILY_REGISTRATION_LIMIT) {
160	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
161	        }
162	        // Bulk-signup warning: flag this owner when more than 80 owners have already been created
163	        // for its registration date, signalling a bulk-signup surge.
164	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
165	        // Per-city capacity: a city that already holds the maximum number of owners is full.
166	        if (this.clinicService.countOwnersInCity(owner.getCity()) >= CITY_CAPACITY) {
167	            return new ResponseEntity<>(HttpStatus.CONFLICT);
168	        }
169	        // The household id is derived deterministically on the owner itself (see
170	        // Owner.getHouseholdId()) from its normalized last name and postcode, so owners sharing a
171	        // last name and postcode share it automatically — no linking step and no ordering to manage.
172	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
173	        // Exact-identity hard duplicate: reject with 409 when the new owner's WHOLE identityKey
174	        // (normalized telephone | email-or-empty | householdId) equals an existing owner's. A
175	        // truly identical record is always rejected, independent of sharesHousehold.
176	        if (this.clinicService.isIdentityKeyInUse(owner)) {
177	            return new ResponseEntity<>(HttpStatus.CONFLICT);
178	        }
179	        // Household duplicate: another owner already belongs to this (last name, postcode)
180	        // household. Reject with 409 unless the caller declares the shared household via
181	        // sharesHousehold, which bypasses the block and creates this owner as a declared member.
182	        boolean householdInUse = this.clinicService.isHouseholdInUse(owner);
183	        if (householdInUse && !sharesHousehold) {
184	            return new ResponseEntity<>(HttpStatus.CONFLICT);
185	        }
186	        // Soft "possible duplicate" detection: an existing owner shares this owner's last name and
187	        // postcode with a different telephone. A declared household member (sharesHousehold on an
188	        // in-use household) is an intentional share, not a suspected duplicate, so it is not
189	        // flagged; otherwise the create still proceeds, flagged with possibleDuplicate=true and
190	        // possibleDuplicateOf set to the matching owner id.
191	        Integer possibleDuplicateOf = (householdInUse && sharesHousehold)
192	            ? null
193	            : this.clinicService.findPossibleDuplicateOwnerId(owner);
194	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
195	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
196	        owner.setNamesakeCount(
197	            this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
198	        this.clinicService.saveOwner(owner);
199	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
200	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
201	            ownerMapper.formatMembershipLevel(owner), ownerMapper.formatMembershipNumber(owner));
202	        if (hasIdempotencyKey) {
203	            idempotencyKeys.put(idempotencyKey, owner.getId());
204	        }
205	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
206	        headers.setLocation(UriComponentsBuilder.newInstance()
207	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
208	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
209	    }
