225	        currentOwner.setEmail(ownerMapper.normalizeEmail(ownerFieldsDto.getEmail()));
226	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
227	        this.clinicService.saveOwner(currentOwner);
228	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
229	    }
