266	        if (currentOwner != null) {
267	            Pet currentPet = this.clinicService.findPetById(petId);
268	            if (currentPet != null) {
269	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
270	                currentPet.setName(petFieldsDto.getName());
271	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
272	                this.clinicService.savePet(currentPet);
273	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
274	            }
275	        }
276	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
277	    }
